INSERT INTO DONGPRODUCT (
	SEQ
	,SUBJECT
	,STATUS
	,IMAGE_KEY
	,ADD_DATE
	,ADD_USER_ID
) VALUES (
	(SELECT NVL(MAX(SEQ),0) + 1 FROM DONGPRODUCT)
	,#{SUBJECT}
	,'C'
	,#{IMAGE_KEY}
	,SYSDATE
	,#{st_user_id}
)


